/**
 * Trash Page - Shows deleted items
 * 
 * Responsibilities:
 * - Display items in trash
 * - Allow restore and permanent delete
 */

import React from 'react';
import { useTrash } from '../../hooks/useTrash';
import FileItem from '../../components/FileItem/FileItem';
import FolderItem from '../../components/FolderItem/FolderItem';

const Trash = () => {
  const { trashItems, loading, error, restoreItem, permanentlyDelete } = useTrash();

  if (loading) {
    return (
      <div className="loading-container">
        <div className="loading-spinner"></div>
        <p>Loading trash...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="error-container">
        <p>Error: {error}</p>
      </div>
    );
  }

  const handleRestore = async (itemId, itemType) => {
    try {
      await restoreItem(itemId, itemType);
    } catch (error) {
      alert(`Failed to restore: ${error.message}`);
    }
  };

  const handleDelete = async (itemId) => {
    if (window.confirm('Are you sure you want to permanently delete this item?')) {
      try {
        await permanentlyDelete(itemId);
      } catch (error) {
        alert(`Failed to delete: ${error.message}`);
      }
    }
  };

  return (
    <div className="trash-page">
      <div className="page-header">
        <h2>Trash</h2>
        <p className="page-subtitle">Items in trash will be permanently deleted after 30 days</p>
      </div>

      {trashItems.length === 0 ? (
        <div className="empty-state">
          <div className="empty-icon">🗑️</div>
          <p>Trash is empty</p>
        </div>
      ) : (
        <div className="file-grid">
          {trashItems.map((item) => (
            <div key={item.id} className="trash-item-wrapper">
              {item.resource_type === 'folder' ? (
                <FolderItem
                  folder={item}
                  onNavigate={() => {}} // Disabled in trash
                />
              ) : (
                <FileItem
                  file={item}
                  onDownload={() => {}} // Disabled in trash
                  onDelete={() => handleDelete(item.id)}
                />
              )}
              <div className="trash-actions">
                <button
                  className="btn-restore"
                  onClick={() => handleRestore(item.id, item.resource_type)}
                  title="Restore"
                >
                  Restore
                </button>
                <button
                  className="btn-delete-permanent"
                  onClick={() => handleDelete(item.id)}
                  title="Delete permanently"
                >
                  Delete Forever
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default Trash;
